18	// 覆盖既有元素：后一份数组较短时尾部残留旧元素，元素省略的字段（command、
19	// index、term）也会从相同位置的旧元素继承，等于让用户给出的后一份日志借用了
20	// 前一份的内容。因此这三个数组都用整体替换的包装类型（replicateInputLog 等）
21	// 解码：每一次出现都解进一份全新的切片并整体替换，最后一份数组是什么就保留
22	// 什么，元素省略的数值按默认 0、省略的命令按空字符串解释。
23	type replicateInput struct {
24		CurrentTerm    int                    `json:"currentTerm"`
25		CommittedIndex int                    `json:"committedIndex"`
26		Log            replicateInputLog      `json:"log"`
27		ApplyKV        bool                   `json:"applyKV"`
28		Requests       replicateInputRequests `json:"requests"`
29	}
